import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { PrismaClient } from '@prisma/client';
import OpenAI from 'openai';

export class VectorSearchRagService {
  private prisma: PrismaClient;
  private openai: OpenAI;

  constructor(prismaClient: PrismaClient) {
    this.prisma = prismaClient;
    this.openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
  }

  public async generateEmbedding(text: string): Promise<number[]> {
    const response = await this.openai.embeddings.create({
      model: 'text-embedding-3-small',
      input: text.replace(/\n/g, ' '),
    });
    return response.data[0].embedding;
  }

  public async indexDocumentChunk(documentId: string, content: string, chunkIndex: number): Promise<string> {
    const embedding = await this.generateEmbedding(content);
    const vectorString = `[${embedding.join(',')}]`;

    const result = await this.prisma.$executeRaw`
      INSERT INTO "DocumentChunk" (id, "documentId", content, "chunkIndex", embedding)
      VALUES (gen_random_uuid(), ${documentId}, ${content}, ${chunkIndex}, ${vectorString}::vector)
    `;
    return `Indexed chunk ${chunkIndex} for document ${documentId}`;
  }

  public async similaritySearch(query: string, documentId?: string, matchThreshold: number = 0.7, matchCount: number = 5):
    Promise<Array<{ id: string; content: string; similarity: number }>> {
    const queryEmbedding = await this.generateEmbedding(query);
    const vectorString = `[${queryEmbedding.join(',')}]`;

    const results = await this.prisma.$queryRaw<Array<{ id: string; content: string; similarity: number }>>`
      SELECT id, content, 1 - (embedding <=> ${vectorString}::vector) as similarity
      FROM "DocumentChunk"
      ${documentId ? this.prisma.$queryRaw`WHERE "documentId" = ${documentId}` : this.prisma.$queryRaw``}
      WHERE 1 - (embedding <=> ${vectorString}::vector) > ${matchThreshold}
      ORDER BY embedding <=> ${vectorString}::vector
      LIMIT ${matchCount};
    `;
    return results;
  }
}

import OpenAI from 'openai';
import { GoogleGenerativeAI } from '@google/genai';
import Anthropic from '@anthropic-ai/sdk';

export type AIProviderType = 'openai' | 'gemini' | 'groq' | 'anthropic';

export interface GenerationOptions {
  provider: AIProviderType;
  model?: string;
  temperature?: number;
  maxTokens?: number;
}

export class AIProviderRouter {
  private openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY || '' });
  private gemini = new GoogleGenerativeAI({ apiKey: process.env.GEMINI_API_KEY || '' });
  private groq = new OpenAI({ apiKey: process.env.GROQ_API_KEY || '', baseURL: 'https://api.groq.com/openai/v1' });
  private anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY || '' });

  public async generateCompletion(prompt: string, options: GenerationOptions): Promise<string> {
    const temp = options.temperature ?? 0.7;
    const tokens = options.maxTokens ?? 1500;

    switch (options.provider) {
      case 'openai': {
        const res = await this.openai.chat.completions.create({
          model: options.model || 'gpt-4o',
          messages: [{ role: 'user', content: prompt }],
          temperature: temp,
          max_tokens: tokens,
        });
        return res.choices[0]?.message?.content || '';
      }
      case 'groq': {
        const res = await this.groq.chat.completions.create({
          model: options.model || 'llama-3.3-70b-versatile',
          messages: [{ role: 'user', content: prompt }],
          temperature: temp,
          max_tokens: tokens,
        });
        return res.choices[0]?.message?.content || '';
      }
      case 'gemini': {
        const modelClient = this.gemini.getGenerativeModel({ model: options.model || 'gemini-1.5-pro' });
        const result = await modelClient.generateContent(prompt);
        return result.response.text();
      }
      case 'anthropic': {
        const res = await this.anthropic.messages.create({
          model: options.model || 'claude-3-5-sonnet-20241022',
          max_tokens: tokens,
          temperature: temp,
          messages: [{ role: 'user', content: prompt }],
        });
        const contentBlock = res.content[0];
        return contentBlock.type === 'text' ? contentBlock.text : '';
      }
      default:
        throw new Error(`Unsupported AI provider: ${options.provider}`);
    }
  }
}
